const {JSDOM}=require('jsdom'),fs=require('fs'),assert=require('node:assert/strict');
const root=require('node:path').resolve(__dirname,'../students')+'/';
const dom=new JSDOM(fs.readFileSync(root+'labs.html','utf8'),{url:'http://localhost/students/labs.html#stability',runScripts:'outside-only'}),w=dom.window,doc=w.document;
const errors=[];w.addEventListener('error',e=>errors.push(e.message));
w.eval(fs.readFileSync(root+'lab-models.js','utf8'));w.eval(fs.readFileSync(root+'labs.js','utf8'));
let checks=0;const ok=(v,msg)=>{assert.ok(v,msg);checks++};
const change=(form,name,value)=>{const e=doc.getElementById(form+'-form').elements.namedItem(name);e.value=String(value);e.dispatchEvent(new w.Event('change',{bubbles:true}))};
ok(doc.getElementById('stability-results').textContent.includes('1.36 m'),'initial GM rendered');
ok(doc.querySelectorAll('#gz-chart path').length===2,'two GZ curves drawn');
ok(doc.getElementById('controls').hidden&&doc.getElementById('engine').hidden,'only selected lab visible');
change('stability','divisions',2);ok(doc.getElementById('stability-results').textContent.includes('0.026 m'),'subdivision recalculates FSC');
change('stability','displacement',0);ok(!doc.getElementById('stability-error').hidden,'invalid displacement feedback');
change('stability','displacement',10000);ok(doc.getElementById('stability-error').hidden,'valid value clears error');
w.location.hash='#controls';w.dispatchEvent(new w.HashChangeEvent('hashchange'));ok(!doc.getElementById('controls').hidden&&doc.getElementById('stability').hidden,'deep-linked controls navigation');
ok(doc.getElementById('signal-result').textContent==='12.000 mA','transmitter default');
change('signal','inverse','true');change('signal','value',12);ok(doc.getElementById('signal-result').textContent==='5.000 engineering units','inverse scaling interaction');
change('signal','urv',0);ok(!doc.getElementById('signal-error').hidden,'zero-span error');
doc.getElementById('signal-answer').value='5';doc.getElementById('signal-check').click();ok(doc.getElementById('signal-feedback').textContent.startsWith('Correct'),'interactive answer evaluation');
ok(doc.querySelectorAll('#pid-chart path').length===3,'SP PV output curves');
change('pid','ti',0);ok(doc.getElementById('pid-results').textContent.includes('PV 46.67%'),'P-only offset rendered');
w.location.hash='#engine';w.dispatchEvent(new w.HashChangeEvent('hashchange'));ok(!doc.getElementById('engine').hidden,'engine navigation');
const initial=doc.getElementById('engine-results').textContent;change('engine','cycles','1');ok(initial!==doc.getElementById('engine-results').textContent,'cycle selection changes power');
ok(doc.querySelectorAll('#fuel-chart rect').length===4,'four fuel comparison bars');
change('engine','bore','');ok(!doc.getElementById('engine-error').hidden,'blank numeric input rejected');
ok(JSON.parse(w.localStorage.getItem('mt-student-labs-v1')).version===1,'versioned local study state stored');
ok(errors.length===0,'no jsdom runtime errors');
console.log(JSON.stringify({status:'PASS',checks,scope:'jsdom HTML/script integration; not Chromium, layout or offline QA'}));
